520:         let mut plan = self.resolve_plan(request)?;
521:         let admission_ids = self.registry.preallocate_admission_ids();
522:         let prepared = self.materialize_input_bindings(
523:             request,
524:             &request_identity_digest,
525:             &admission_ids.job_id,
526:             inputs,
527:         )?;
528:         plan.input_set_id = Some(prepared.input_set_id.clone());
529:         plan.effective_inputs = prepared.effective_inputs.clone();
530:         plan.env.insert(
531:             "ORDIVON_INPUT_ROOT".to_string(),
532:             CONTAINED_INPUT_ROOT.to_string(),
533:         );
534:         for step in &mut plan.steps {
535:             step.env.insert(
536:                 "ORDIVON_INPUT_ROOT".to_string(),
537:                 CONTAINED_INPUT_ROOT.to_string(),
538:             );
539:         }
540:         let submit = SubmitRequest {
541:             schema_version: RUNTIME_SCHEMA_VERSION,
542:             client_request_id: request.client_request_id.clone(),
543:             request_identity_digest: Some(request_identity_digest),
544:             execution_provider: Some(
545:                 self.current_execution_provider_snapshot(request.execution.execution_target)?,
546:             ),
547:             runtime_release_effect: None,
548:             host_dependencies: Vec::new(),
549:             plan,
550:             global_limit: request.global_limit,
551:         };
552:         match self.registry.submit_preallocated(&submit, &admission_ids) {
553:             Ok(AdmissionOutcome::Created(created)) => {
554:                 let job_id = created.job.job_id.clone();
555:                 self.ensure_job_input_ownership(&job_id)
556:                     .map_err(|error| error.with_operation_id(job_id.clone()))?;
557:                 self.ensure_attempt_dispatched(&created.attempt)
