562:                 self.discard_prepared_input_set(&prepared.prepared_root)?;
563:                 Ok(job.job_id)
564:             }
565:             Err(error) => {
566:                 self.discard_prepared_input_set(&prepared.prepared_root)?;
567:                 Err(error)
568:             }
569:         }
570:     }
