2366:     fn await_launch_evidence(&self, attempt: &AttemptRecord) -> RuntimeResult<()> {
2367:         let deadline = Instant::now()
2368:             .checked_add(Duration::from_millis(self.startup_grace_ms))
2369:             .ok_or_else(|| {
2370:                 RuntimeError::invalid(
2371:                     "startupGraceMs exceeds platform monotonic clock range",
2372:                     "startupGraceMs",
2373:                 )
2374:             })?;
2375:         let plan = self.registry.execution_plan(&attempt.job_id)?;
2376:         let start_path = Path::new(&attempt.bundle_path).join(match plan.execution_target {
2377:             super::ExecutionTarget::LocalLinux => RUNNER_START_FILE,
2378:             super::ExecutionTarget::WindowsNative => WINDOWS_START_FILE,
2379:         });
2380:         let mut poll_index = 0;
2381:         loop {
2382:             if Path::new(&attempt.bundle_path).join(RESULT_FILE).exists() {
2383:                 return self.reconcile_runner_result(attempt);
2384:             }
2385:             if start_path.exists() {
2386:                 match self.bind_attempt_start(attempt, plan.execution_target) {
2387:                     Ok(_) => return Ok(()),
2388:                     Err(error) if error.code == RuntimeErrorCode::LaunchIdentityMismatch => {
2389:                         // A very short-lived unit can write valid start evidence, finish, and be
2390:                         // unloaded between the filesystem check and systemctl_show. A complete
2391:                         // identity-bound Runner result is stronger terminal evidence than the
2392:                         // already-disappeared transient unit.
2393:                         if Path::new(&attempt.bundle_path).join(RESULT_FILE).exists() {
2394:                             return self.reconcile_runner_result(attempt);
2395:                         }
2396:                         thread::sleep(Duration::from_millis(20));
2397:                         if Path::new(&attempt.bundle_path).join(RESULT_FILE).exists() {
2398:                             return self.reconcile_runner_result(attempt);
2399:                         }
2400:                         return Err(error);
2401:                     }
2402:                     Err(error) => return Err(error),
2403:                 }
2404:             }
2405:             if Instant::now() >= deadline {
2406:                 break;
2407:             }
2408:             sleep_until_poll(deadline, &mut poll_index);
2409:         }
2410:         self.reconcile_attempt(&attempt.attempt_id)
2411:     }
