5455: fn read_tail_text(path: &Path, max_bytes: u64) -> RuntimeResult<String> {
5456:     if max_bytes == 0 || !path.exists() {
5457:         return Ok(String::new());
5458:     }
5459:     let mut file = File::open(path).map_err(|error| io_error("open output tail", error))?;
5460:     let length = file
5461:         .metadata()
5462:         .map_err(|error| io_error("inspect output tail", error))?
5463:         .len();
5464:     let offset = length.saturating_sub(max_bytes);
5465:     file.seek(SeekFrom::Start(offset))
5466:         .map_err(|error| io_error("seek output tail", error))?;
5467:     let mut bytes = Vec::with_capacity(usize::try_from(max_bytes.min(length)).unwrap_or(0));
5468:     file.take(max_bytes)
5469:         .read_to_end(&mut bytes)
5470:         .map_err(|error| io_error("read output tail", error))?;
5471:     Ok(String::from_utf8_lossy(&bytes).into_owned())
5472: }
